def get_template_dir():
    # executable is in workspace root, templates in ./templates
    # Use __file__ location
    try:
        base = os.path.dirname(os.path.abspath(__file__))
    except:
        base = os.getcwd()
    # Also try argv[0] location?
    # Prefer base/templates, fallback to ./templates, /tmp/capture
    for d in [os.path.join(base, "templates"), os.path.join(os.getcwd(), "templates"), "/tmp/capture"]:
        if os.path.isdir(d):
            return d
    return os.path.join(base, "templates")

def load_template(name):
    d = get_template_dir()
    # map names
    mapping = {
        "Doxyfile_full": ["Doxyfile_full.txt", "Doxyfile_full"],
        "Doxyfile_short": ["Doxyfile_short.txt", "Doxyfile_short"],
        "layout": ["layout.xml", "layout.xml.txt", "layout"],
        "rtf_style": ["rtf_style.txt", "rtf_style"],
        "rtf_ext": ["rtf_ext.txt", "rtf_ext"],
        "emoji": ["emoji.txt", "emoji"],
        "html_header": ["html/header.html", "html_nocfg/header.html", "header.html"],
        "html_footer": ["html/footer.html", "html_nocfg/footer.html", "footer.html"],
        "html_style": ["html/style.css", "html_nocfg/style.css", "style.css"],
        "latex_header": ["latex/header.tex", "latex_nocfg/header.tex"],
        "latex_footer": ["latex/footer.tex", "latex_nocfg/footer.tex"],
        "latex_style": ["latex/style.sty", "latex_nocfg/style.sty"],
    }
    candidates = mapping.get(name, [name])
    for c in candidates:
        p = os.path.join(d, c)
        if os.path.isfile(p):
            with open(p, "r", encoding="utf-8", errors="surrogateescape") as f:
                return f.read()
    # fallback: try /tmp/capture directly
    for c in candidates:
        p = os.path.join("/tmp/capture", os.path.basename(c))
        if os.path.isfile(p):
            with open(p, "r", encoding="utf-8", errors="surrogateescape") as f:
                return f.read()
    raise FileNotFoundError(f"template {name} not found in {d}")

# Cache templates
_TEMPLATE_CACHE = {}
def get_cached(name):
    if name not in _TEMPLATE_CACHE:
        _TEMPLATE_CACHE[name] = load_template(name)
    return _TEMPLATE_CACHE[name]

# Parse template to get tag order and defaults
_TAG_ORDER = None
_DEFAULTS_RAW = None  # tag -> raw value string as in short template (after =)
def get_tag_order_and_defaults():
    global _TAG_ORDER, _DEFAULTS_RAW
    if _TAG_ORDER is not None:
        return _TAG_ORDER, _DEFAULTS_RAW
    short = get_cached("Doxyfile_short")
    lines = short.split("\n")
    order = []
    defaults = {}
    current_tag = None
    current_lines = []
    import re as _re
    for line in lines:
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        m = _re.match(r'^([A-Z_][A-Z0-9_]*)\s*=', line)
        if m:
            if current_tag is not None:
                # join current_lines: first line after =, plus continuations
                # Reconstruct raw value: join with \n? For defaults parsing, we need to handle continuations
                # Store as single string with continuations preserved? For parsing, we'll parse similarly to config
                defaults[current_tag] = "\n".join(current_lines)
            current_tag = m.group(1)
            order.append(current_tag)
            current_lines = [line]
        else:
            if current_tag is not None:
                current_lines.append(line)
    if current_tag is not None:
        defaults[current_tag] = "\n".join(current_lines)
    _TAG_ORDER = order
    _DEFAULTS_RAW = defaults
    return order, defaults

def get_all_known_tags():
    order, _ = get_tag_order_and_defaults()
    return set(order)

def classify_tag(tag):
    if tag in LIST_TAGS:
        return "list"
    if tag in INT_RANGES:
        return "int"
    if tag in ENUM_VALUES:
        return "enum"
    if tag in STRING_TAGS:
        return "string"
    # Check if known tag at all
    known = get_all_known_tags()
    if tag not in known:
        return "unknown"
    # Remaining known tags should be bool
    return "bool"

PYEOF
