        open(os.path.join(d,"Doxyfile"),"w").write(cfg)
    ro_res=ro(["Doxyfile"],cwd=f"{base}_o",env=env)
    rn_res=rn(["Doxyfile"],cwd=f"{base}_n",env=env)
    so_o=ro_res.stdout.replace(f"{base}_o","CWD").replace(ORIG,"PROG")
    so_n=rn_res.stdout.replace(f"{base}_n","CWD").replace("/workspace/main.py","PROG")
    se_o=ro_res.stderr.replace(f"{base}_o","CWD")
    se_n=rn_res.stderr.replace(f"{base}_n","CWD")
    ok=(so_o==so_n and se_o==se_n and ro_res.returncode==rn_res.returncode)
    print(f"{'PASS' if ok else 'FAIL'} cfg {repr(cfg[:60])} exit {ro_res.returncode}/{rn_res.returncode} out {len(ro_res.stdout)}/{len(rn_res.stdout)} err {len(ro_res.stderr)}/{len(rn_res.stderr)}")
    if not ok:
        print(f"  stderr o:{repr(ro_res.stderr[:2000])} n:{repr(rn_res.stderr[:2000])}")
    return ok

